import { DatabaseSync } from 'node:sqlite';

export interface ChatClient {
  id: string;
  write: (data: string) => void;
  close: () => void;
}

declare global {
  var _chatDb: DatabaseSync | undefined;
  var _chatClients: Set<ChatClient> | undefined;
}

export function getDb(): DatabaseSync {
  if (!globalThis._chatDb) {
    const db = new DatabaseSync('/home/user/qwik-app/chat.db');
    db.exec(`
      CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user TEXT NOT NULL,
        text TEXT NOT NULL,
        timestamp TEXT NOT NULL
      );
    `);
    globalThis._chatDb = db;
  }
  return globalThis._chatDb;
}

export function getClients(): Set<ChatClient> {
  if (!globalThis._chatClients) {
    globalThis._chatClients = new Set<ChatClient>();
  }
  return globalThis._chatClients;
}

export function broadcastMessage(message: { id: number; user: string; text: string; timestamp: string }) {
  const clients = getClients();
  const payload = `data: ${JSON.stringify(message)}\n\n`;
  for (const client of clients) {
    try {
      client.write(payload);
    } catch (err) {
      console.error('Error writing to client:', err);
    }
  }
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getDb, getClients, broadcastMessage } from '../../../chat-db';

export const onGet: RequestHandler = async (requestEvent) => {
  requestEvent.status(200);
  requestEvent.headers.set('Content-Type', 'text/event-stream');
  requestEvent.headers.set('Cache-Control', 'no-cache');
  requestEvent.headers.set('Connection', 'keep-alive');

  const writable = requestEvent.getWritableStream();
  const writer = writable.getWriter();
  const encoder = new TextEncoder();

  const clientId = Math.random().toString(36).substring(2);

  const client = {
    id: clientId,
    write: (data: string) => {
      writer.write(encoder.encode(data));
    },
    close: () => {
      try {
        writer.close();
      } catch (e) {
        // ignore
      }
    }
  };

  getClients().add(client);

  // Fetch all existing messages from the database and stream them immediately
  const db = getDb();
  const select = db.prepare('SELECT id, user, text, timestamp FROM messages ORDER BY id ASC');
  const messages = select.all() as Array<{ id: number; user: string; text: string; timestamp: string }>;

  for (const msg of messages) {
    client.write(`data: ${JSON.stringify(msg)}\n\n`);
  }

  // Return a promise that resolves when the request is aborted
  return new Promise<void>((resolve) => {
    const onAbort = () => {
      getClients().delete(client);
      client.close();
      requestEvent.signal.removeEventListener('abort', onAbort);
      resolve();
    };

    if (requestEvent.signal.aborted) {
      onAbort();
    } else {
      requestEvent.signal.addEventListener('abort', onAbort);
    }
  });
};

export const onPost: RequestHandler = async (requestEvent) => {
  const body = await requestEvent.parseBody() as any;
  if (!body || typeof body !== 'object') {
    requestEvent.json(400, { error: 'Invalid body' });
    return;
  }

  const { user, text } = body;
  if (typeof user !== 'string' || typeof text !== 'string' || user === '' || text === '') {
    requestEvent.json(400, { error: 'User and text must be non-empty strings' });
    return;
  }

  const db = getDb();
  const timestamp = new Date().toISOString();

  const insert = db.prepare('INSERT INTO messages (user, text, timestamp) VALUES (?, ?, ?)');
  const result = insert.run(user, text, timestamp);
  const id = Number(result.lastInsertRowid);

  const savedMessage = { id, user, text, timestamp };

  // Broadcast to all active clients
  broadcastMessage(savedMessage);

  // Return 201 status with the JSON payload
  requestEvent.json(201, savedMessage);
};

import { component$, useStore, useVisibleTask$, $ } from '@builder.io/qwik';
import type { DocumentHead } from '@builder.io/qwik-city';

interface Message {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

interface ChatStore {
  messages: Message[];
  user: string;
  text: string;
}

export default component$(() => {
  const state = useStore<ChatStore>({
    messages: [],
    user: '',
    text: '',
  });

  // Connect to the SSE stream on the client side
  useVisibleTask$(({ cleanup }) => {
    const eventSource = new EventSource('/api/messages');

    eventSource.onmessage = (event) => {
      try {
        const message = JSON.parse(event.data) as Message;
        // Avoid duplicate messages
        const exists = state.messages.some((m) => m.id === message.id);
        if (!exists) {
          state.messages.push(message);
        }
      } catch (err) {
        console.error('Error parsing SSE message:', err);
      }
    };

    eventSource.onerror = (err) => {
      console.error('EventSource error:', err);
    };

    cleanup(() => {
      eventSource.close();
    });
  });

  const handleSubmit = $(async (e: Event) => {
    e.preventDefault();
    if (!state.user.trim() || !state.text.trim()) {
      return;
    }

    try {
      const response = await fetch('/api/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          user: state.user,
          text: state.text,
        }),
      });

      if (response.ok) {
        // Clear inputs after successful submission
        state.user = '';
        state.text = '';
      } else {
        console.error('Failed to post message:', response.statusText);
      }
    } catch (err) {
      console.error('Error posting message:', err);
    }
  });

  return (
    <div style={{ padding: '20px', maxWidth: '600px', margin: '0 auto', fontFamily: 'sans-serif' }}>
      <h1>SSE Real-Time Chat</h1>

      <form onSubmit$={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginBottom: '20px' }}>
        <input
          type="text"
          id="user-input"
          data-testid="user-input"
          value={state.user}
          onInput$={(e) => (state.user = (e.target as HTMLInputElement).value)}
          placeholder="Your name"
          style={{ padding: '8px', fontSize: '16px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
        <input
          type="text"
          id="text-input"
          data-testid="text-input"
          value={state.text}
          onInput$={(e) => (state.text = (e.target as HTMLInputElement).value)}
          placeholder="Type a message..."
          style={{ padding: '8px', fontSize: '16px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
        <button
          type="submit"
          id="send-button"
          data-testid="send-button"
          style={{ padding: '10px', fontSize: '16px', backgroundColor: '#0070f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
        >
          Send
        </button>
      </form>

      <div
        id="message-list"
        data-testid="message-list"
        style={{ border: '1px solid #eee', borderRadius: '4px', padding: '10px', maxHeight: '400px', overflowY: 'auto', backgroundColor: '#f9f9f9' }}
      >
        {state.messages.length === 0 ? (
          <p style={{ color: '#888', textAlign: 'center' }}>No messages yet. Say hello!</p>
        ) : (
          state.messages.map((msg) => (
            <div
              key={msg.id}
              class="message-item"
              data-testid="message-item"
              style={{ padding: '8px', borderBottom: '1px solid #eee', marginBottom: '4px' }}
            >
              <strong style={{ color: '#0070f3' }}>{msg.user}</strong>:{' '}
              <span>{msg.text}</span>
              <div style={{ fontSize: '12px', color: '#888', marginTop: '4px' }}>
                {new Date(msg.timestamp).toLocaleString()}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: 'Qwik Real-Time SSE Chat',
};

